import java.util.Locale;

public class NumberFormats {
    public static String currency(double amount) {
        return String.format(Locale.ROOT, "EUR %.2f", amount);
    }

    public static String percent(double fraction, int decimals) {
        return String.format(Locale.ROOT, "%." + decimals + "f%%", fraction * 100);
    }
}

test:
public class Test {
    public static void main(String[] a) {
        if (!(NumberFormats.percent(0.5, 0).equals("50%"))) throw new AssertionError("0 decimals");
        if (!(NumberFormats.percent(0.1234, 1).equals("12.3%"))) throw new AssertionError("1 decimal");
        if (!(NumberFormats.percent(0.1234, 2).equals("12.34%"))) throw new AssertionError("2 decimals");
        if (!(NumberFormats.currency(3.5).equals("EUR 3.50"))) throw new AssertionError("currency unchanged");
        System.out.println("PASS");
    }
}
